package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.service.content.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

/** Actual native sent attempt and exact whole-day result permission, before content application. */
class CatalogDayAnalysisResultPermitTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisDispatchTest helper(){return new CatalogDayAnalysisDispatchTest(){@Override boolean mysql(){return CatalogDayAnalysisResultPermitTest.this.mysql();}};}
    record Built(CatalogDayAnalysisDispatchTest helper,CatalogDayAnalysisDispatchTest.Built data,ResultApplicationService.Input input,CatalogDayAnalysisResultPermitService permits){ }
    Built fixture(String category,boolean alias){var helper=helper();var data=helper.fixture(category,alias);var nativeData=data.data().data().data();var claim=data.worker().claim(helper.action("result-permit-claim"));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());assertEquals(WorkerAuthorizationService.State.SENT,data.worker().dispatch(claim.permit(),request->"fictional result permission response").state());var f=nativeData.f().f;var content=new ContentReadService(new JdbcContentReads(f.source),f.tx,ContentReadService.denyUnverifiedReferences());var store=new ResultJdbcStore(f.source,claim.permit().identity(),content,target->data.validity().exactVersionExists(target)&&data.validity().validity(target).effectiveValid(),data.clock(),"analysis-worker");var input=nativeData.outer().snapshot(nativeData.f(),store::input);return new Built(helper,data,input,new CatalogDayAnalysisResultPermitService(helper.helper().provider(data.data()),category));}
    @Test void FourCategoriesExactSentInputCanGrantOnlyTheCapturedApplicationMode(){for(String category:List.of("agent","skill","workflow","model")){var built=fixture(category,false);var data=built.data().data().data().data();var permit=built.permits().capture(built.input(),false);int jobs=data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);assertDoesNotThrow(()->data.f().write(()->{built.permits().verify(permit,built.input(),false);return true;}));assertThrows(RuntimeException.class,()->data.f().write(()->{built.permits().verify(permit,built.input(),true);return true;}));assertEquals(jobs,data.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,data.f().f.sends);assertFalse(permit.toString().contains("fictional"));}}
    @Test void ExplicitManualReviewRevisionAdvanceKeepsOriginalBodyAndRootFixed(){var built=fixture("agent",true);var data=built.data().data().data().data();var automatic=built.permits().capture(built.input(),false);data.f().f.jdbc.update("UPDATE contents SET revision=revision+1");assertThrows(RuntimeException.class,()->data.f().write(()->{built.permits().verify(automatic,built.input(),false);return true;}));var manual=built.permits().capture(built.input(),true);assertDoesNotThrow(()->data.f().write(()->{built.permits().verify(manual,built.input(),true);return true;}));assertThrows(RuntimeException.class,()->data.f().write(()->{data.f().f.jdbc.update("UPDATE contents SET input_job_id='fictional-forged-body-root'");built.permits().verify(manual,built.input(),true);return true;}));assertEquals(2,data.f().f.sends);}
    @Test void OriginalInputMismatchCurrentGenerationAndNativeOldProofDamageNeverGrantApplication(){var built=fixture("model",true);var data=built.data().data().data().data();var permit=built.permits().capture(built.input(),false);var context=(ObjectNode)CanonicalJson.parse(built.data().data().input().snapshotJson()).get(FrozenApplicationContext.FIELD);context.put("target_entity_id","fictional-other-entity");var forged=FrozenApplicationContext.fromJson(context).input(built.input().rootId(),built.input().attemptId(),built.input().inputHash(),built.input().expectedRootRevision());assertThrows(RuntimeException.class,()->built.permits().capture(forged,false));assertThrows(RuntimeException.class,()->data.f().write(()->{data.f().f.jdbc.update("UPDATE analyzed_entities SET analysis_generation=analysis_generation+1");built.permits().verify(permit,built.input(),false);return true;}));assertThrows(RuntimeException.class,()->data.f().write(()->{data.f().f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE owner_job_id=? AND purpose='result'",new byte[32],CatalogPreviousAnalysisTest.Fixture.ROOT);built.permits().verify(permit,built.input(),false);return true;}));assertEquals(2,data.f().f.sends);}
    @Test void IssuerModeAndTransactionBoundariesRejectBeforeAnyBusinessApplication(){var built=fixture("workflow",false);var data=built.data().data().data().data();var permit=built.permits().capture(built.input(),false);assertThrows(RuntimeException.class,()->built.permits().verify(permit,built.input(),false));assertThrows(RuntimeException.class,()->data.f().write(()->built.permits().capture(built.input(),false)));var other=new CatalogDayAnalysisResultPermitService(built.helper().helper().provider(built.data().data()),"workflow");assertThrows(RuntimeException.class,()->data.f().write(()->{other.verify(permit,built.input(),false);return true;}));assertThrows(RuntimeException.class,()->data.outer().snapshot(data.f(),()->{built.permits().verify(permit,built.input(),false);return true;}));var original=mock(CatalogDayAnalysisDispatchPermitService.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogDayAnalysisResultPermitService(original,category));verifyNoInteractions(original);assertThrows(RuntimeException.class,()->new CatalogDayAnalysisResultPermitService(original,"news_tech"));assertEquals(2,data.f().f.sends);}
}
